module poly8_v9_8b (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [15:0] r0, r1, r2, r3, r4, r5, r6, r7, r8;
    reg  [7:0] xd1, xd2, xd3, xd4, xd5, xd6, xd7, xd8;
    always @(posedge clk) begin
        if (!rst_n) y <= 16'd0;
        else        y <= r8;
        r0 <= 16'd65;
        xd1 <= x;
        r1 <= 16'd30 * xd1 + r0;
        xd2 <= xd1;
        r2 <= 16'd3 * xd2 + r1;
        xd3 <= xd2;
        r3 <= 16'd97 * xd3 + r2;
        xd4 <= xd3;
        r4 <= 16'd7 * xd4 + r3;
        xd5 <= xd4;
        r5 <= 16'd99 * xd5 + r4;
        xd6 <= xd5;
        r6 <= 16'd95 * xd6 + r5;
        xd7 <= xd6;
        r7 <= 16'd42 * xd7 + r6;
        xd8 <= xd7;
        r8 <= 16'd1 * xd8 + r7;
    end
endmodule

